using System.Collections.Frozen;
using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// High-throughput product catalog optimized for read-heavy lookup workloads.
/// Uses FrozenDictionary for cache-friendly reads, a reverse index to eliminate
/// linear scans, and SIMD-vectorized summation for batch price calculations.
/// </summary>
public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    // Frozen snapshots for read-hot paths
    private FrozenDictionary<string, string>? _frozenCategories;
    private FrozenDictionary<string, double>? _frozenPrices;
    private FrozenDictionary<string, string[]>? _frozenCategoryIndex;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = (double)price;

        if (!_categoryIndex.TryGetValue(category, out var list))
        {
            list = new List<string>();
            _categoryIndex[category] = list;
        }
        list.Add(code);

        // Invalidate frozen snapshots on mutation
        _frozenCategories = null;
        _frozenPrices = null;
        _frozenCategoryIndex = null;
    }

    /// <summary>
    /// Call after bulk loading to freeze dictionaries for optimal read throughput.
    /// </summary>
    public void Freeze()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenCategoryIndex = _categoryIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        var cats = _frozenCategories;
        if (cats is not null)
            return cats.TryGetValue(code, out var cat) ? cat : null;

        return _categories.TryGetValue(code, out var c) ? c : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var prices = _frozenPrices ?? (FrozenDictionary<string, double>?)null;

        // Resolve prices into a contiguous buffer for vectorized summation
        Span<double> buffer = codes.TryGetNonEnumeratedCount(out int count) && count <= 256
            ? stackalloc double[count]
            : new double[count = 0];

        int written = 0;

        if (buffer.Length > 0)
        {
            foreach (var code in codes)
            {
                if (prices is not null
                    ? prices.TryGetValue(code, out var p)
                    : _prices.TryGetValue(code, out p))
                {
                    buffer[written++] = p;
                }
            }

            return (decimal)SimdSum(buffer[..written]);
        }

        // Fallback for unknown-length enumerables: accumulate into a list then vectorize
        var priceList = new List<double>();
        foreach (var code in codes)
        {
            if (prices is not null
                ? prices.TryGetValue(code, out var p)
                : _prices.TryGetValue(code, out p))
            {
                priceList.Add(p);
            }
        }

        return (decimal)SimdSum(CollectionsMarshal.AsSpan(priceList));
    }

    public List<string> GetProductsByCategory(string category)
    {
        // O(1) reverse-index lookup instead of full scan
        var frozen = _frozenCategoryIndex;
        if (frozen is not null)
            return frozen.TryGetValue(category, out var arr) ? new List<string>(arr) : [];

        return _categoryIndex.TryGetValue(category, out var list) ? new List<string>(list) : [];
    }

    /// <summary>
    /// SIMD-accelerated summation over a contiguous span of doubles.
    /// Uses hardware vector width for maximum throughput on AVX2/AVX-512/NEON.
    /// </summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0.0;

        var vectors = MemoryMarshal.Cast<double, Vector<double>>(values);
        var vSum = Vector<double>.Zero;

        for (int i = 0; i < vectors.Length; i++)
            vSum += vectors[i];

        double sum = Vector.Sum(vSum);

        // Handle remaining elements that don't fill a full vector
        int vectorized = vectors.Length * Vector<double>.Count;
        for (int i = vectorized; i < values.Length; i++)
            sum += values[i];

        return sum;
    }
}

